"""Per-joint PD gain tables for Shadow / Sharpa / Wuji hands.

See ``docs/hand_controller_parameters.md`` for the upstream sources and the
derivation of each number. Keep this file in sync with that doc.
"""

import math


def _strip_side(name: str) -> str:
    """Strip a ``left_`` / ``right_`` prefix; pass other names through."""
    for prefix in ("left_", "right_"):
        if name.startswith(prefix):
            return name[len(prefix):]
    return name


def gains_to_list(joint_names, gain_dict):
    """Map a list of (possibly side-prefixed) joint names to gain values."""
    return [gain_dict[_strip_side(n)] for n in joint_names]


