# =============================================================================
# Contact plant + transmission rules shared by the hands we are allowed to tune
# =============================================================================
# Four-layer contract L2: pads are 1.2/1.2 with patch 0.005/0.002, everything
# else on the hand is EXPLICIT 0.35/0.35. The trap the contract calls out is the
# one both of these hands were in: a material list that names only the tip
# frames. Measured:
#
#   * xhand's ``*_tip`` links are 5x3x3 mm, 0.03 cm^3 and 3.5e-8 kg reference
#     markers -- and they stick out 1.8-2.55 mm PAST the distal phalanx, so every
#     pinch in sim made first contact through a 35-microgram nub while the real
#     pad (``*_link2``, 12.7 cm^3) sat on the engine fallback 0.30 with ZERO
#     torsional friction;
#   * wuji's tip caps are real (2.2 cm^3) but its distal phalanx ``link4`` was
#     also left on the fallback.
#
# So: pads go on the links that carry load, the marker frames keep their pose
# role and lose their collision, and every remaining hand link is stated.
PAD_MU = 1.2                      # silicone pad, docs/friction_calibration.md S2
PAD_PATCH_RADIUS = 0.005          # contact patch pressed, m (torsional lever)
PAD_MIN_PATCH_RADIUS = 0.002      # contact patch on light touch, m


def hand_urdf_config(pad_links) -> dict:
    """ManiSkill ``urdf_config`` for a hand: the load-bearing PADS only.

    The non-pad shell is stated by the shared hook
    ``tasks.config.contact_materials.apply_dex_hand_contact_materials`` (same
    split sharpa already uses), so the flange adapter stays classified as Panda
    structure at 0.30 instead of being claimed by the hand.
    """
    return dict(
        _materials=dict(
            fingertip=dict(static_friction=PAD_MU, dynamic_friction=PAD_MU, restitution=0.0),
        ),
        link={n: dict(material="fingertip", patch_radius=PAD_PATCH_RADIUS,
                      min_patch_radius=PAD_MIN_PATCH_RADIUS) for n in pad_links},
    )


# Joint transmission dry friction, as a fraction of the joint's own force limit.
# The only vendor-MEASURED anchor we have is the sharpa MJCF, whose frictionloss
# is a consistent 2-4% of force_limit at every joint (CMC 4.0%, MCP 4.0%,
# PIP 2.0%, DIP 2.0%). Wuji's MJCF declares NO frictionloss at all and xhand's
# third-party conversion used a flat 2e-3 (0.18-0.5%), i.e. an order below the
# anchor -- neither is credible for a geared finger, and this term is what holds
# a grasp when the servo is not pushing. 3% = the middle of the measured anchor.
FRICTIONLOSS_FRACTION = 0.03

# Reflected rotor inertia per N*m of joint torque capability. Anchor: the two
# hands that ship a real per-joint armature land at armature/force_limit =
# 0.9-2.2e-3 (sharpa) and 0.8-1.0e-3 (wuji). xhand's flat 2e-4 on all 12 joints
# is a MJCF-conversion default that ignores the 2.75x spread in its own actuator
# classes and leaves the rotor at 17-49% of the joint's true inertia, where every
# comparable hand has it dominant.
ARMATURE_PER_NM = 1.0e-3

# Joint speed ceiling. SAPIEN's default is 100 rad/s (955 rpm at the joint),
# which is not a spec, just "unset": no dexterous finger moves at 16 revolutions
# per second, and an unbounded joint turns a restored demo state or a large
# command step into a finger that teleports through the object it should grasp.
# 20 rad/s sits above the teleop's own finger slew limit (--hand-speed 16 rad/s)
# so it never fights the operator, and ~5x above the fastest human finger close.
HAND_JOINT_MAX_VELOCITY = 20.0


# Fingertip force floor, fleet-wide.
# ---------------------------------------------------------------------------
# The benchmark already declares how strong a hand must be: the four-layer
# contract's graspability rule sizes every task object against sharpa's distal
# joint, 0.1894 N*m over a 0.025 m lever = 7.58 N at the fingertip
# (check_four_layer_alignment.py: DIP_TORQUE, DIP_LEVER). An object is only
# allowed into a task if two fingers at that force can hold it.
#
# Measured, per finger, taking the WEAKEST joint in the chain (in a
# grasp the whole chain has to hold, so the weakest link is the hand's real
# strength):
#
#     sharpa   7.3 N      xhand   9.4 N (index 3.4)      wuji   1.9 N
#
# So wuji could hold ~0.39 kg where the benchmark assumes 1.55 kg, and the
# operator's report -- "wuji is clearly weaker, it can't push through a task" --
# is a 4x shortfall against the fleet's own standard, not a matter of feel.
# The culprit is one joint class: wuji's ABDUCTION limit is 0.182 N*m on a 9.7 cm
# lever, a tenth of sharpa's and a quarter of xhand's.
#
# The rule raises any joint that cannot deliver the benchmark force, and NEVER
# lowers a vendor value:
#
#     force_limit = max(vendor, FLEET_FINGERTIP_FORCE * lever)
#
# This is a deliberate, authorised departure from vendor-faithful
# force limits for wuji and xhand, taken because task completion outranks a
# vendor number we cannot verify on hardware. It touches 18/20 wuji joints
# (largest x4.04) and exactly ONE xhand joint (index abduction, x2.20) -- the
# rest of xhand already clears the bar, which is why it feels fine.
# Sharpa is untouched: it IS the benchmark.
FLEET_FINGERTIP_FORCE = 7.58            # N at the fingertip, every joint


def _raise_to_fleet_force(vendor_limit: dict, lever: dict) -> dict:
    return {j: max(vendor_limit[j], FLEET_FINGERTIP_FORCE * lever[j]) for j in vendor_limit}


def _derive_frictionloss(force_limit: dict) -> dict:
    return {j: FRICTIONLOSS_FRACTION * fl for j, fl in force_limit.items()}


def _derive_armature(force_limit: dict) -> dict:
    return {j: ARMATURE_PER_NM * fl for j, fl in force_limit.items()}


# =============================================================================
# Shared servo-gain rule for the hands whose vendor kp we do NOT inherit
# =============================================================================
# WHY a rule instead of the vendor number (decision, measured):
#
#   force_limit is a HARDWARE constant and every hand's is fine — converted
#   through the measured moment arms, the three hands' fingertip force ceilings
#   agree (distal 7.3 / 7.6 / 9.4 N for sharpa / wuji / xhand).
#
#   kp is NOT hardware. It is the vendor's own servo tuning, and the three
#   vendors disagree by 5-23x, so the same physical class of device behaved like
#   three different machines in sim: at a typical 3 mm of retargeted fingertip
#   penetration the grip came out 0.12 N (wuji) / 1.3 N (sharpa) / 3.1 N (xhand).
#
#   Worse, a pure proportional drive is not what the real firmware runs. A real
#   position servo has integral action, so at steady state it reaches its torque
#   ceiling at essentially ZERO tracking error; the sim spring reaches it only at
#   force_limit/kp. With the vendor kp, a wuji finger needed 95 deg of tracking
#   error to reach its own ceiling -- MORE than the joint's entire 98.5 deg of
#   travel, i.e. it could never develop its rated force at all (measured on a
#   bare-PhysX bench: loaded past 0.5 N*m the joint stops at its travel limit,
#   never at its force limit). That is a control-completeness failure, not a
#   faithful model of a weak hand.
#
# THE RULE: a joint reaches its own vendor force ceiling at FINGERTIP_FORCE_TRAVEL
# of fingertip deflection.
#
#     kp = force_limit * lever / FINGERTIP_FORCE_TRAVEL          [N*m/rad]
#     kd = 2 * zeta * sqrt(kp * (armature + downstream link inertia))
#
# so tip stiffness = F_tip_max / FINGERTIP_FORCE_TRAVEL, i.e. every finger of
# every hand is equally "stiff relative to its own strength", and each hand keeps
# its true, vendor-sourced force ceiling.
#
# CHOICE OF THE CONSTANT: the same quantity, back-computed for hands in the
# field, spans ~10-80 mm (xhand as shipped 11 mm, LEAP ~25 mm, sharpa here 41 mm,
# Allegro ~56 mm, Shadow/IsaacGym ~81 mm). We take the stiff end: 10 mm of
# fingertip deflection to full rated force is a physically ordinary contact
# deflection, and the soft end is exactly where this repo's history of "the hand
# cannot hold anything" came from. Re-tune HERE if the operator wants softer --
# it is one number and the tests check consistency, not the value.
FINGERTIP_FORCE_TRAVEL = 0.010          # m of fingertip travel to full torque
HAND_DAMPING_RATIO = 1.0                # critical damping, on the TRUE inertia


def _derive_kp(force_limit: dict, lever: dict) -> dict:
    """kp [N*m/rad] such that force_limit is reached at FINGERTIP_FORCE_TRAVEL."""
    return {j: force_limit[j] * lever[j] / FINGERTIP_FORCE_TRAVEL for j in force_limit}


def _derive_damping(kp: dict, armature: dict, link_inertia: dict) -> dict:
    """kd for HAND_DAMPING_RATIO against the inertia the drive REALLY sees.

    Deriving kd from the armature alone (the previous xhand formula) silently
    under-damps whenever the armature is not the dominant term: measured, the
    xhand armature is only 17-49% of the true effective inertia, so its nominal
    zeta=1 table actually delivered zeta = 0.41-0.70 (thumb root worst).
    """
    return {j: 2 * HAND_DAMPING_RATIO * math.sqrt(kp[j] * (armature[j] + link_inertia[j]))
            for j in kp}


