WUJI_HAND_FORCE_LIMIT = _raise_to_fleet_force(_WUJI_VENDOR_FORCE_LIMIT, _WUJI_LEVER)

# Servo gains derived by the shared rule (see FINGERTIP_FORCE_TRAVEL above).
WUJI_HAND_KP = _derive_kp(WUJI_HAND_FORCE_LIMIT, _WUJI_LEVER)
WUJI_HAND_DAMPING = _derive_damping(WUJI_HAND_KP, WUJI_HAND_ARMATURE, _WUJI_LINK_INERTIA)
# The wuji MJCF declares no joint friction at all; a geared finger has some, and
