def wuji_pad_links(prefix: str = "right_") -> list:
    return ([f"{prefix}finger{f}_link4" for f in WUJI_FINGERS]
            + [f"{prefix}finger{f}_tip_link" for f in WUJI_FINGERS])






# Public alias: the sharpa reflected-rotor-inertia table (same dict used to
# derive SHARPA_HAND_DAMPING above). Ported to the sim joints.
SHARPA_HAND_ARMATURE = _SHARPA_ARMATURE


# -----------------------------------------------------------------------------
# RobotEra XHand1 (Shadow replacement)
# -----------------------------------------------------------------------------
# 12 fully-decoupled active joints (thumb 3, index 3, mid/ring/pinky 2). Keys
# are the *unprefixed* joint names (post ``_strip_side``): the composite URDF
# names them ``right_hand_<...>``, so ``_strip_side`` yields ``hand_<...>``.
#
# PROVENANCE (see memory xhand1-replaces-shadow + docs/hand_controller_parameters):
#   force_limit : VENDOR-GRADE. Official RobotEra URDF v1.3 ``<limit effort>``,
#     two actuator classes only — strong 1.1 N*m, weak 0.4 N*m. Cross-confirmed
#     by 3 independent ports (tsingqingyun MJCF, RoboVerse Isaac cfg, Genesis)
#     and the product manual (12 N/finger grip). This is the grip-force ceiling
#     and it is NOT invented — anchor on it.
#   kp        : NO LONGER the third-party MuJoCo reproduction (which was strong
#     10 / weak 4, i.e. a two-class constant that ignored the 3x spread in the
#     joints' moment arms). Derived by the shared servo rule above from the
#     VENDOR force ceiling and the measured lever, so the proximal joints barely
#     move (10 -> 10.8-14.8) while the short-lever distal joints, which the flat
#     table made 2.4x too stiff for their own torque ceiling, come down to
#     1.7-2.0. _XHAND_THIRD_PARTY_KP below keeps the old numbers for A/B.
#   armature / frictionloss : tsingqingyun MJCF conversion defaults
#     (2e-4 / 2e-3). Physically defensible for a QDD *back-drivable* hand (low
#     reflected inertia, low transmission friction) but not hardware-measured.
#   damping   : derived like sharpa — kd = 2*zeta*sqrt(kp*armature) with
#     zeta = 1.0 (the MJCF uses actuator dampratio=1). The MJCF's extra static
#     joint damping (0.02) is small and folded into this critical-damping value.
#
# NOTE: the official URDF's own ``<dynamics damping="1" friction="1">`` are
# generic SolidWorks-export placeholders — deliberately IGNORED here in favour
# of the above.

_XHAND_STRONG = [  # proximal / MCP-flexion + thumb base: effort 1.1, kp 10
    "hand_thumb_bend_joint", "hand_thumb_rota_joint1",
    "hand_index_joint1", "hand_mid_joint1", "hand_ring_joint1", "hand_pinky_joint1",
]
_XHAND_WEAK = [  # distal / PIP-flexion + index abduction + thumb IP: effort 0.4, kp 4
    "hand_thumb_rota_joint2", "hand_index_bend_joint",
    "hand_index_joint2", "hand_mid_joint2", "hand_ring_joint2", "hand_pinky_joint2",
]
_XHAND_JOINTS = _XHAND_STRONG + _XHAND_WEAK

_XHAND_THIRD_PARTY_KP = {**{j: 10.0 for j in _XHAND_STRONG}, **{j: 4.0 for j in _XHAND_WEAK}}
_XHAND_VENDOR_FORCE_LIMIT = {**{j: 1.1 for j in _XHAND_STRONG}, **{j: 0.4 for j in _XHAND_WEAK}}
_XHAND_CONVERSION_ARMATURE = {j: 2e-4 for j in _XHAND_JOINTS}      # replaced, kept for A/B
_XHAND_CONVERSION_FRICTIONLOSS = {j: 2e-3 for j in _XHAND_JOINTS}  # replaced, kept for A/B

