# Contact link sets. Pads = the distal phalanges (``*_link2``, 12.7 cm^3, the
# skin-covered segment that actually presses on objects). The ``*_tip`` frames
# are 5x3x3 mm markers -- they keep the pad material so the retargeting target
# and the pad agree, but their collision is masked off in the agent's
# _after_init (see XHAND_MARKER_LINKS): they are 3.5e-8 kg and protrude past the
# real pad, so leaving them collidable meant every pinch contacted through them.
_XHAND_FINGERS = ("index", "mid", "ring", "pinky")


def xhand_pad_links(prefix: str = "right_") -> list:
    return [f"{prefix}hand_thumb_rota_link2", f"{prefix}hand_index_rota_link2"] + [
        f"{prefix}hand_{f}_link2" for f in ("mid", "ring", "pinky")
    ] + xhand_marker_links(prefix)[:5]





def xhand_marker_links(prefix: str = "right_") -> list:
    """Collision-less reference frames: the 5 fingertip markers + the ee frame."""
    return [f"{prefix}hand_thumb_rota_tip", f"{prefix}hand_index_rota_tip"] + [
        f"{prefix}hand_{f}_tip" for f in ("mid", "ring", "pinky")
    ] + [f"{prefix}hand_ee_link"]


def apply_joint_physics(robot, hand_joint_names, frictionloss=None, armature=None,
                        max_velocity=None, no_collision_links=()):
    """Apply vendor-MJCF joint transmission physics to a BUILT articulation:
    Coulomb dry friction (``joint.set_friction``) and reflected rotor inertia
    (``PhysxArticulationJoint.set_armature``). These are frozen REAL physical
    properties (sim2real) — never runtime knobs. Call from the agent's
    ``_after_init`` (re-runs on every reconfigure, so rebuilds keep them).

    Without armature the sim finger carries only the link inertia (often 20-30x
    smaller than the reflected rotor inertia), which both misstates the dynamics
    and breaks the damping-ratio math: the MJCF-derived kd assumes armature, so
    a no-armature joint runs ~4-5x overdamped.

    ``max_velocity`` caps the joint speed (SAPIEN's unset default is 100 rad/s).
    ``no_collision_links`` masks the collision of pose-only reference frames (the
    zero-mass fingertip markers), which otherwise take the first contact of every
    grasp; they stay in the articulation so retargeting and FK are unchanged."""
    fl = (dict(zip(hand_joint_names, gains_to_list(hand_joint_names, frictionloss)))
          if frictionloss else {})
    ar = (dict(zip(hand_joint_names, gains_to_list(hand_joint_names, armature)))
          if armature else {})
    for j in robot.get_active_joints():
        f = fl.get(j.name)
        if f is not None and hasattr(j, "set_friction"):
            j.set_friction(float(f))
        a = ar.get(j.name)
        if a is not None:
            for pj in getattr(j, "_objs", []):
                if hasattr(pj, "set_armature"):
                    pj.set_armature([float(a)])
        if max_velocity is not None and _strip_side(j.name) in (
                {_strip_side(n) for n in hand_joint_names}):
            for pj in getattr(j, "_objs", []):
                if hasattr(pj, "set_max_velocity"):
                    pj.set_max_velocity(float(max_velocity))

    if no_collision_links:
        wanted = set(no_collision_links)
        for link in robot.get_links():
            if link.name not in wanted:
                continue
            for component in getattr(link, "_objs", []):
                for shape in component.get_collision_shapes():
                    groups = shape.get_collision_groups()
                    groups[1] = 0          # collide with nothing
                    shape.set_collision_groups(groups)
